using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Reflection;using System.ServiceProcess;using System.Configuration.Install;using System.Security.AccessControl;using System.Security.Principal;using System.Windows.Forms;using Microsoft.Win32;using ContourWatch;
class Setup {
 static string Dest=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"ContourWatch");
 [STAThread]static int Main(string[] args){Application.EnableVisualStyles();Agent.ConfigureTls();try{if(args.Length>0&&args[0]=="--help"){Console.WriteLine("ContourSetup.exe --silent --server=https://host --token-file=C:\\secure\\token.txt [--name=PC] [--group=Office]\n--uninstall removes program but preserves identity and queue. --reregister clears device credentials and uses a new enrollment token.");return 0;}
  var p=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string a in args){var v=a.Split(new[]{'='},2);p[v[0]]=v.Length>1?v[1]:"true";}
  if(!Environment.Is64BitOperatingSystem)throw new Exception("Эта сборка предназначена для x64. x86 не проверена.");
  using(var k=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\NET Framework Setup\NDP\v4\Full")){if(k==null||Convert.ToInt32(k.GetValue("Release",0))<528040)throw new Exception("Требуется .NET Framework 4.8. Установите официальный автономный пакет Microsoft и повторите установку.");}
  if(p.ContainsKey("--check-connection")){Agent.CheckConnection(p["--check-connection"]);return 0;}
  if(p.ContainsKey("--uninstall")){Uninstall(p.ContainsKey("--silent"));return 0;}
  if(p.ContainsKey("--silent")){if(!p.ContainsKey("--server"))throw new Exception("Нужен --server");string token=p.ContainsKey("--token-file")?File.ReadAllText(p["--token-file"]).Trim():"";Install(p["--server"],token,p.ContainsKey("--name")?p["--name"]:Environment.MachineName,p.ContainsKey("--group")?p["--group"]:"Без группы",p.ContainsKey("--reregister"));return 0;}
  Application.Run(new Wizard());return 0;
 }catch(Exception e){if(Array.IndexOf(args,"--silent")>=0)Console.Error.WriteLine(e.Message);else MessageBox.Show(e.Message,"Контур · ошибка",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
 static string Describe(Exception ex){var parts=new List<string>();for(var e=ex;e!=null;e=e.InnerException){var native=e as System.ComponentModel.Win32Exception;parts.Add(e.Message+(native==null?"":" [Win32 "+native.NativeErrorCode+"]"));}return String.Join(" → ",parts.ToArray());}
 static void Stop(){try{using(var s=new ServiceController("ContourWatch")){if(s.Status!=ServiceControllerStatus.Stopped){s.Stop();s.WaitForStatus(ServiceControllerStatus.Stopped,TimeSpan.FromSeconds(30));}}}catch(InvalidOperationException){}}
 static void Run(string exe,string args){using(var p=Process.Start(new ProcessStartInfo(exe,args){UseShellExecute=false,CreateNoWindow=true})){if(!p.WaitForExit(30000)){p.Kill();throw new System.TimeoutException("Не завершилась системная команда");}if(p.ExitCode!=0)throw new Exception("Ошибка системной команды: "+exe);}}
 static void Secure(string path,bool usersRead){var sec=new DirectorySecurity();sec.SetAccessRuleProtection(true,false);foreach(var sid in new[]{WellKnownSidType.LocalSystemSid,WellKnownSidType.BuiltinAdministratorsSid})sec.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid,null),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));if(usersRead)sec.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(WellKnownSidType.BuiltinUsersSid,null),FileSystemRights.ReadAndExecute,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.SetAccessControl(path,sec);}
 static bool SameFile(string a,string b){if(!File.Exists(a)||!File.Exists(b))return false;using(var hash=System.Security.Cryptography.SHA256.Create())using(var left=File.OpenRead(a))using(var right=File.OpenRead(b))return Convert.ToBase64String(hash.ComputeHash(left))==Convert.ToBase64String(hash.ComputeHash(right));}
 static bool ResourceChanged(string name){string target=Path.Combine(Dest,name);if(!File.Exists(target))return true;using(var source=Assembly.GetExecutingAssembly().GetManifestResourceStream(name))using(var existing=File.OpenRead(target))using(var hash=System.Security.Cryptography.SHA256.Create())return Convert.ToBase64String(hash.ComputeHash(source))!=Convert.ToBase64String(hash.ComputeHash(existing));}
 static void StopInstalledTray(){string expected=Path.GetFullPath(Path.Combine(Dest,"ContourTray.exe"));foreach(var process in Process.GetProcessesByName("ContourTray")){using(process){if(process.HasExited)continue;string executable=Path.GetFullPath(process.MainModule.FileName);if(!String.Equals(expected,executable,StringComparison.OrdinalIgnoreCase))continue;if(!process.CloseMainWindow()||!process.WaitForExit(1500)){process.Kill();if(!process.WaitForExit(5000))throw new System.TimeoutException("Не удалось завершить установленный значок трея");}}}}
 // Called only after SCM has stopped the service. Isolated collector children
 // may still hold the agent image; never terminate a same-named foreign path.
 static void StopSensorWorkers(){foreach(string name in new[]{"ContourAgent","ContourSensorWorker"}){string expected=Path.GetFullPath(Path.Combine(Dest,name+".exe"));foreach(var p in Process.GetProcessesByName(name)){using(p){try{if(!p.HasExited&&String.Equals(Path.GetFullPath(p.MainModule.FileName),expected,StringComparison.OrdinalIgnoreCase)){p.Kill();if(!p.WaitForExit(5000))throw new System.TimeoutException("Сборщик не остановился: "+name);}}catch(InvalidOperationException){if(!p.HasExited)throw;}}}}}
 static void ExtractHardware(){string destination=Path.Combine(Dest,"sensors");Directory.CreateDirectory(destination);using(var archive=System.IO.Compression.ZipFile.OpenRead(Path.Combine(Dest,"hardware.zip"))){foreach(var entry in archive.Entries){if(entry.FullName.IndexOf('/')>=0||entry.FullName.IndexOf('\\')>=0||!entry.Name.EndsWith(".dll",StringComparison.OrdinalIgnoreCase))continue;string file=Path.Combine(destination,entry.Name);using(var input=entry.Open())using(var output=File.Create(file))input.CopyTo(output);}}}
 static void Extract(string name){using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream(name))using(var f=File.Create(Path.Combine(Dest,name))){if(s==null)throw new IOException("Ресурс отсутствует: "+name);s.CopyTo(f);}}
 static void Install(string server,string token,string name,string group,bool reregister){Agent.Endpoint(server,"/health",false);if(String.IsNullOrWhiteSpace(name)||name.Length>200||String.IsNullOrWhiteSpace(group)||group.Length>200)throw new Exception("Укажите имя и группу длиной до 200 символов.");Directory.CreateDirectory(Agent.Root);Secure(Agent.Root,false);Directory.CreateDirectory(Path.Combine(Agent.Root,"public"));Secure(Path.Combine(Agent.Root,"public"),true);
  var c=File.Exists(Path.Combine(Agent.Root,"config.json"))?Agent.Config():new Dictionary<string,object>();if(!c.ContainsKey("secret")||reregister){if(String.IsNullOrWhiteSpace(token))throw new Exception("Нужен токен подключения");c.Remove("secret");c.Remove("id");c.Remove("requestId");c.Remove("deviceSecret");c["token"]=Agent.Protect(token);}else if(Agent.Get(c,"server").TrimEnd('/')!=server.TrimEnd('/'))throw new Exception("При смене сервера включите повторную регистрацию и задайте новый токен.");
  c["server"]=server;c["name"]=name;c["group"]=group;Directory.CreateDirectory(Dest);Secure(Dest,true);var changed=new List<string>();foreach(string file in new[]{"ContourAgent.exe","ContourAgent.exe.config","ContourTray.exe","ContourTray.exe.config","agent.ico","ContourSensorWorker.exe","ContourSensorWorker.exe.config","hardware.zip","hardware-LICENSE.txt","hardware-modules-COPYING.txt","hardware-NOTICE.md"})if(ResourceChanged(file))changed.Add(file);
  if(changed.Contains("ContourTray.exe")||changed.Contains("ContourTray.exe.config")||changed.Contains("agent.ico"))StopInstalledTray();Stop();StopSensorWorkers();
  foreach(string file in changed)Extract(file);if(changed.Contains("hardware.zip")||!File.Exists(Path.Combine(Dest,"sensors","LibreHardwareMonitorLib.dll")))ExtractHardware();Agent.SaveConfig(c);
  string self=Assembly.GetExecutingAssembly().Location,target=Path.Combine(Dest,"ContourSetup.exe");if(!String.Equals(self,target,StringComparison.OrdinalIgnoreCase)&&!SameFile(self,target))File.Copy(self,target,true);
  bool exists=true;try{using(var svc=new ServiceController("ContourWatch")){var state=svc.Status;}}catch(InvalidOperationException){exists=false;}
  if(!exists){var process=new ServiceProcessInstaller{Account=ServiceAccount.LocalSystem};var service=new ServiceInstaller{ServiceName="ContourWatch",DisplayName="Контур · мониторинг оборудования",Description="Исходящий сбор показателей оборудования. Входящий порт не открывается.",StartType=ServiceStartMode.Automatic};process.Installers.Add(service);process.Context=new InstallContext(null,new[]{"/assemblypath="+Path.Combine(Dest,"ContourAgent.exe")});process.Install(new Hashtable());}
  Run("sc.exe","failure ContourWatch reset= 86400 actions= restart/10000/restart/30000/restart/60000");Run("sc.exe","failureflag ContourWatch 1");
  using(var k=Registry.LocalMachine.CreateSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Run"))k.SetValue("ContourWatchTray","\""+Path.Combine(Dest,"ContourTray.exe")+"\"");
  using(var k=Registry.LocalMachine.CreateSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\ContourWatch")){k.SetValue("DisplayName","Контур / ContourWatch");k.SetValue("DisplayVersion",Agent.Version);k.SetValue("Publisher","ContourWatch");k.SetValue("UninstallString","\""+target+"\" --uninstall");k.SetValue("InstallLocation",Dest);}
  try{using(var svc=new ServiceController("ContourWatch")){svc.Start();svc.WaitForStatus(ServiceControllerStatus.Running,TimeSpan.FromSeconds(30));}}catch(Exception ex){throw new Exception("Не удалось запустить службу. "+Describe(ex)+" Журнал: "+Path.Combine(Agent.Root,"agent.log"),ex);}
 }
 static void Uninstall(bool quiet){StopInstalledTray();Stop();StopSensorWorkers();Run("sc.exe","delete ContourWatch");using(var k=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Run",true))if(k!=null)k.DeleteValue("ContourWatchTray",false);Registry.LocalMachine.DeleteSubKeyTree(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\ContourWatch",false);
  foreach(string f in new[]{"ContourAgent.exe","ContourAgent.exe.config","ContourTray.exe","ContourTray.exe.config","agent.ico"}){string path=Path.Combine(Dest,f);try{File.Delete(path);}catch{}}if(!quiet)MessageBox.Show("Служба удалена. Настройки, очередь и сам установщик сохранены для восстановления. Их можно удалить вручную после проверки.","Контур");}
 class Wizard:Form {
  TextBox server=new TextBox(),token=new TextBox(),name=new TextBox(),group=new TextBox();CheckBox re=new CheckBox{Text="Повторная регистрация (новый токен)",AutoSize=true};Button test=new Button{Text="Проверить соединение",Width=200},install=new Button{Text="Установить / сохранить",Width=200};Label result=new Label{AutoSize=true,MaximumSize=new Size(430,0)};
  public Wizard(){Text="Контур · установка агента";Width=560;Height=760;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(28)};Controls.Add(flow);FormClosing+=(s,e)=>{if(!install.Enabled)e.Cancel=true;};
   flow.Controls.Add(new Label{Text="Контур / Windows-агент",Font=new Font(Font,FontStyle.Bold),AutoSize=true});Add(flow,"HTTPS адрес сервера",server);Add(flow,"Токен подключения",token);token.UseSystemPasswordChar=true;Add(flow,"Имя компьютера",name);Add(flow,"Группа",group);name.Text=Environment.MachineName;group.Text="Без группы";
   try{var c=Agent.Config();server.Text=Agent.Get(c,"server");name.Text=Agent.Get(c,"name",name.Text);group.Text=Agent.Get(c,"group",group.Text);}catch{}
   flow.Controls.Add(re);var pawn=new Button{Text="Открыть официальный сайт драйвера PawnIO",Width=435};pawn.Click+=(s,e)=>Process.Start(new ProcessStartInfo("https://pawnio.eu/"){UseShellExecute=true});flow.Controls.Add(pawn);flow.Controls.Add(new Label{Text="Температура CPU и вентиляторы платы требуют подписанный PawnIO. GPU NVIDIA использует nvidia-smi из драйвера. Защиту Windows отключать не нужно.",AutoSize=true,MaximumSize=new Size(435,0)});flow.Controls.Add(test);flow.Controls.Add(install);flow.Controls.Add(result);
   test.Click+=async(s,e)=>{test.Enabled=false;try{string url=server.Text;await System.Threading.Tasks.Task.Run(()=>Agent.CheckConnection(url));result.Text="Соединение и сертификат проверены.";}catch(Exception ex){result.Text="Нет соединения: "+ex.Message+". Можно установить и подключиться позднее.";}finally{test.Enabled=true;}};
   install.Click+=async(s,e)=>{install.Enabled=false;test.Enabled=false;try{string u=server.Text,t=token.Text,n=name.Text,g=group.Text;bool r=re.Checked;await System.Threading.Tasks.Task.Run(()=>Install(u,t,n,g,r));result.Text="Служба установлена и запущена. Значок трея появится после входа пользователя.";}catch(Exception ex){result.Text=ex.Message;}finally{install.Enabled=true;test.Enabled=true;}};
  }
  static void Add(Control flow,string label,TextBox box){flow.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(0,12,0,4)});box.Width=435;flow.Controls.Add(box);}
 }
}


